import 'dart:convert';import 'dart:io';
import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';
import 'package:flutter_core/communication_modules.dart';
import 'package:flutter_core/preference_sync/preference_protocol.dart';
import 'package:flutter_core/component_catalogue/prime_component_catalogue.dart';
final scope=PreferenceScope('tenant','actor','registered-role','live');
const longId='mail:fixture-mailbox:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
Map<String,Object?> data(String module,{int version=1,String body='Literal <script>private text</script>'})=>{'scope':scope.toJson(),'module':module,'items':[{'id':longId,'version':version,'title':'Registered record','body':body,'date':'','lane':'','meta':'Stored status','actions':module=='messenger'?<Map<String,Object?>>[{'id':'send','label':'Send fixture','fields':['body'],'target':''}]:<Map<String,Object?>>[]}],'lanes':<Map<String,Object?>>[],'offset':0,'total':1,'partial':false};
class Port implements WorkPort{final String module;bool lose=false;int calls=0;final keys=<String>[];Map<String,Object?> value;Port(this.module):value=data(module);@override Future<Object?> read(WorkQuery q)async=>value;@override Future<WorkReceipt> mutate(WorkCommand c,String key)async{keys.add(key);calls++;value=data(module,version:c.version+1,body:c.fields['body']!);if(lose&&calls==1)throw Exception('lost reply');return WorkReceipt(c.itemId,c.version+1,c.action,{'body':c.fields['body']!});}@override Future<Object?> readItem(String id)async=>value;@override void dispose(){}}
void main(){final raw=jsonDecode(File('../primecare_ui/catalogs/communication-modules.registration.json').readAsStringSync()),labels=CatalogueLabels.fromMetadata(raw,'en');
 test('registered communication IDs retain deterministic long-ID semantics',(){expect(recordSuffix(longId).length,greaterThan(160));expect(labels.id('open','prime_button',suffix:'-${recordSuffix(longId)}'),startsWith('communication-modules-open-'));expect(()=>recordSuffix('a'*201),throwsA(isA<WorkFailure>()));expect(()=>labels.id('open','prime_button',suffix:'-${'a'*401}'),throwsArgumentError);});
 for(final module in ['mailbox','messenger','files','notifications']){testWidgets('$module is a scoped optional view with no invented create/delete action',(t)async{await t.binding.setSurfaceSize(const Size(1200,1600));addTearDown(()=>t.binding.setSurfaceSize(null));final port=Port(module),session=WorkModuleSession(scope,module,port:module=='notifications'?null:port,requestId:()=> '00000000-0000-4000-8000-000000000001');await t.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeWorkModule(labels:labels,session:session,scope:'actor',year:2026,month:11,gap:8,boardWidth:250)))));await t.pumpAndSettle();expect(t.takeException(),isNull);final create=t.widget<TextButton>(find.widgetWithText(TextButton,labels.text('create')).first);expect(create.onPressed,isNull);if(module=='notifications'){expect(session.status,'unavailable');expect(find.text('Registered record'),findsNothing);}else{expect(find.text('Literal <script>private text</script>'),findsOneWidget);await t.tap(find.widgetWithText(TextButton,labels.text('open')).first);await t.pumpAndSettle();expect(t.takeException(),isNull);expect(find.text(labels.text('success')),findsNothing);if(module!='messenger')expect(find.widgetWithText(TextButton,labels.text('save')),findsNothing);}await t.pumpWidget(const SizedBox());session.dispose();});}
 testWidgets('visible confirmation retries the original message key and retains failed draft',(t)async{await t.binding.setSurfaceSize(const Size(1200,1600));addTearDown(()=>t.binding.setSurfaceSize(null));final port=Port('messenger')..lose=true,session=WorkModuleSession(scope,'messenger',port:port,requestId:()=> '00000000-0000-4000-8000-000000000001');await t.pumpWidget(MaterialApp(home:Scaffold(body:SingleChildScrollView(child:PrimeWorkModule(labels:labels,session:session,scope:'actor',year:2026,month:11,gap:8,boardWidth:250)))));await t.pumpAndSettle();await t.tap(find.widgetWithText(TextButton,labels.text('open')).first);await t.pumpAndSettle();await t.enterText(find.byType(TextField).last,'Retained private draft');await t.tap(find.widgetWithText(TextButton,labels.text('save')).first);await t.pumpAndSettle();expect(session.pending,isNotNull);expect(find.text('Retained private draft'),findsOneWidget);await t.tap(find.widgetWithText(TextButton,labels.text('retry')).first);await t.pumpAndSettle();expect(session.status,'success');expect(port.keys.length,2);expect(port.keys.first,port.keys.last);expect(t.takeException(),isNull);await t.pumpWidget(const SizedBox());session.dispose();});
}
